import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    alice_fish = list(map(int, data[3:3+n]))
    bob_fish = list(map(int, data[3+n:3+n+m]))

    alice_count = [0] * k
    bob_count = [0] * k

    for fish in alice_fish:
        alice_count[fish-1] += 1

    for fish in bob_fish:
        bob_count[fish-1] += 1

    alice_only = False
    bob_only = False

    for i in range(k):
        if alice_count[i] > bob_count[i]:
            alice_only = True
        if bob_count[i] > alice_count[i]:
            bob_only = True

    if alice_only and not bob_only:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
